cat > src/merge.js <<'EOF'
function changes(base, side, who) {
  const n = base.length, m = side.length
  const L = Array.from({ length: n + 1 }, () => new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--)
    for (let j = m - 1; j >= 0; j--)
      L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
  const res = []
  let i = 0, j = 0, bs = 0, ss = 0
  const flush = () => {
    if (i > bs || j > ss) res.push({ bs, be: i, ss, se: j, who })
  }
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      flush()
      i++; j++; bs = i; ss = j
    } else if (L[i + 1][j] >= L[i][j + 1]) i++
    else j++
  }
  i = n; j = m
  flush()
  return res
}

const eq = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])

export function merge(mode, mine, base, theirs) {
  const all = [...changes(base, mine, 0), ...changes(base, theirs, 1)]
  all.sort((a, b) => a.bs - b.bs || a.who - b.who)
  const regions = []
  let k = 0, pos = 0
  while (k < all.length) {
    const start = all[k].bs
    let end = all[k].be
    const group = [all[k++]]
    while (k < all.length && all[k].bs <= end) {
      end = Math.max(end, all[k].be)
      group.push(all[k++])
    }
    if (start > pos) regions.push({ kind: 'stable', lines: base.slice(pos, start) })
    pos = end
    const baseLines = base.slice(start, end)
    const side = (who, doc) => {
      const cs = group.filter(c => c.who === who)
      if (!cs.length) return baseLines
      const mn = Math.min(...cs.map(c => c.bs)), mx = Math.max(...cs.map(c => c.be))
      const s = Math.min(...cs.map(c => c.ss)) - (mn - start)
      const e = Math.max(...cs.map(c => c.se)) + (end - mx)
      return doc.slice(s, e)
    }
    const m = side(0, mine), t = side(1, theirs)
    if (group.length === 1) {
      regions.push({ kind: group[0].who === 0 ? 'mine' : 'theirs', lines: group[0].who === 0 ? m : t })
    } else if (eq(m, t)) regions.push({ kind: 'both', lines: m })
    else if (eq(m, baseLines)) regions.push({ kind: 'theirs', lines: t })
    else if (eq(t, baseLines)) regions.push({ kind: 'mine', lines: m })
    else regions.push({ kind: 'conflict', m, b: baseLines, t })
  }
  if (pos < base.length) regions.push({ kind: 'stable', lines: base.slice(pos) })
  const out = []
  let conflict = false
  for (const r of regions) {
    if (r.kind === 'conflict') conflict = true
    if (mode === 'regions') {
      out.push(r.kind === 'conflict' ? `conflict mine=${r.m.length} base=${r.b.length} theirs=${r.t.length}` : `${r.kind} ${r.lines.length}`)
    } else if (r.kind === 'conflict') {
      out.push('<<<<<<< mine', ...r.m)
      if (mode === 'merge') out.push('||||||| base', ...r.b)
      out.push('=======', ...r.t, '>>>>>>> theirs')
    } else out.push(...r.lines)
  }
  return { out, conflict }
}
