{"command":"cat package.json; cat > src/cli.js <<'EOF'
const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

class Failure extends Error {}

function parse(s) {
  const m = /^(?:([^:/?#]+):)?(?:\/\/([^/?#]*))?([^?#]*)(?:\?([^#]*))?(?:#([\s\S]*))?$/.exec(s)
  const r = { scheme: m[1], path: m[3], query: m[4], fragment: m[5] }
  if (m[2] !== undefined) {
    const a = m[2]
    const at = a.lastIndexOf('@')
    const userinfo = at >= 0 ? a.slice(0, at) : undefined
    const hp = a.slice(at + 1)
    const colon = hp.indexOf(':', hp.lastIndexOf(']') + 1 || 0)
    r.userinfo = userinfo
    r.host = colon >= 0 ? hp.slice(0, colon) : hp
    r.port = colon >= 0 ? hp.slice(colon + 1) : undefined
    r.hasAuthority = true
  }
  return r
}

function checkPercent(r, line) {
  for (const k of ['path', 'userinfo', 'host', 'query', 'fragment']) {
    const v = r[k]
    if (v !== undefined && /%(?![0-9A-Fa-f]{2})/.test(v)) {
      throw new Failure(`error: line ${line}: the ${k} has a truncated percent-encoding`)
    }
  }
}

function normPct(s) {
  if (s === undefined) return s
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return /[A-Za-z0-9\-._~]/.test(c) ? c : '%' + h.toUpperCase()
  })
}

function removeDots(path) {
  let inp = path
  let out = ''
  while (inp) {
    if (inp.startsWith('../')) inp = inp.slice(3)
    else if (inp.startsWith('./')) inp = inp.slice(2)
    else if (inp.startsWith('/./')) inp = inp.slice(2)
    else if (inp === '/.') inp = '/'
    else if (inp.startsWith('/../') || inp === '/..') {
      inp = inp === '/..' ? '/' : inp.slice(3)
      out = out.slice(0, Math.max(out.lastIndexOf('/'), 0))
    } else if (inp === '.' || inp === '..') inp = ''
    else {
      const i = inp.indexOf('/', 1)
      const seg = i < 0 ? inp : inp.slice(0, i)
      out += seg
      inp = inp.slice(seg.length)
    }
  }
  return out
}

function normalize(r) {
  const scheme = r.scheme === undefined ? undefined : r.scheme.replace(/[A-Z]/g, c => c.toLowerCase())
  let s = ''
  if (scheme !== undefined) s += scheme + ':'
  if (r.hasAuthority) {
    s += '//'
    if (r.userinfo !== undefined) s += normPct(r.userinfo) + '@'
    s += normPct(r.host).replace(/[A-Z]/g, c => c.toLowerCase())
    let port = r.port
    if (port === '' || (scheme !== undefined && port === DEFAULT_PORTS[scheme])) port = undefined
    if (port !== undefined) s += ':' + normPct(port)
  }
  let path = removeDots(normPct(r.path))
  if (r.hasAuthority && path === '') path = '/'
  s += path
  if (r.query !== undefined) s += '?' + normPct(r.query)
  if (r.fragment !== undefined) s += '#' + normPct(r.fragment)
  return s
}

function resolve(base, ref) {
  if (ref.scheme !== undefined) return { ...ref, path: removeDots(ref.path) }
  const t = { scheme: base.scheme, fragment: ref.fragment }
  const auth = o => { t.hasAuthority = o.hasAuthority; t.userinfo = o.userinfo; t.host = o.host; t.port = o.port }
  if (ref.hasAuthority) {
    auth(ref); t.path = removeDots(ref.path); t.query = ref.query
  } else {
    auth(base)
    if (ref.path === '') {
      t.path = base.path
      t.query = ref.query !== undefined ? ref.query : base.query
    } else {
      if (ref.path.startsWith('/')) t.path = removeDots(ref.path)
      else {
        let merged
        if (base.hasAuthority && base.path === '') merged = '/' + ref.path
        else {
          const i = base.path.lastIndexOf('/')
          merged = i < 0 ? ref.path : base.path.slice(0, i + 1) + ref.path
        }
        t.path = removeDots(merged)
      }
      t.query = ref.query
    }
  }
  return t
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'normalize' && mode !== 'resolve')) {
    throw new Failure('error: usage: cli.js normalize|resolve')
  }
  const lines = require_stdin().split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const out = []
  lines.forEach((text, idx) => {
    const n = idx + 1
    let r
    if (mode === 'normalize') {
      r = parse(text)
    } else {
      const sp = text.indexOf(' ')
      if (sp < 0) throw new Failure(`error: line ${n}: expected a base and a reference`)
      const base = parse(text.slice(0, sp))
      if (base.scheme === undefined) throw new Failure(`error: line ${n}: the base has no scheme`)
      r = resolve(base, parse(text.slice(sp + 1)))
    }
    checkPercent(r, n)
    out.push(normalize(r))
  })
  return out.map(l => l + '\n').join('')
}

function require_stdin() {
  return new TextDecoder('utf-8').decode(readAll())
}

function readAll() {
  const fs = process.getBuiltinModule('node:fs')
  const chunks = []
  const buf = Buffer.alloc(65536)
  for (;;) {
    let n
    try { n = fs.readSync(0, buf, 0, buf.length, null) } catch (e) {
      if (e.code === 'EAGAIN') continue
      if (e.code === 'EOF') break
      throw e
    }
    if (n === 0) break
    chunks.push(Buffer.from(buf.subarray(0, n)))
  }
  return Buffer.concat(chunks)
}

try {
  process.stdout.write(main())
} catch (e) {
  if (!(e instanceof Failure)) throw e
  process.stderr.write(e.message + '\n')
  process.exitCode = 2
}
EOF
