  } catch { return null }
}

// misplaced range check (static)
function misplaced(e, direct) {
  switch (e.n) {
    case 'range': return !direct
    case 'bin': return misplaced(e.l, false) || misplaced(e.r, false)
    case 'un': return misplaced(e.x, false)
    case 'call': return e.args.some((a) => misplaced(a, true))
    default: return false
  }
}

function rangeCells(e) {
  const a = parseAddr(e.a), b = parseAddr(e.b)
  if (!a || !b) return null
  const out = []
  for (let c = Math.min(a.c, b.c); c <= Math.max(a.c, b.c); c++)
    for (let r = Math.min(a.r, b.r); r <= Math.max(a.r, b.r); r++) out.push({ c, r })
  return out
}

function collect(e, set) {
  switch (e.n) {
    case 'ref': { const a = parseAddr(e.w); if (a) set.set(key(a), a); break }
    case 'range': { const cs = rangeCells(e); if (cs) for (const a of cs) set.set(key(a), a); break }
    case 'bin': collect(e.l, set); collect(e.r, set); break
    case 'un': collect(e.x, set); break
    case 'call': e.args.forEach((x) => collect(x, set)); break
  }
}

// ---- parse all formulas
for (const cell of cells.values()) {
  const c = cell.content
  if (c[0] === '=') {
    const ast = parse(c.slice(1))
    cell.ast = ast
    cell.bad = !ast || misplaced(ast, false)
  }
}

if (mode[0] === 'deps') {
  const out = []
  const sorted = [...cells.values()].sort((x, y) => key(x.a) - key(y.a))
  for (const cell of sorted) {
    let line = `${colName(cell.a.c)}${cell.a.r}:`
    if (cell.ast) {
      const set = new Map()
      collect(cell.ast, set)
      for (const a of [...set.values()].sort((x, y) => key(x) - key(y))) line += ` ${colName(a.c)}${a.r}`
    }
    out.push(line)
  }
  process.stdout.write(out.map((l) => l + '\n').join(''))
  process.exit(0)
}

// ---- evaluation
const memo = new Map()
const active = new Set()

function cellValue(a) {
  const k = key(a)
  if (memo.has(k)) return memo.get(k)
  const cell = cells.get(k)
  if (!cell) return N(0)
  if (active.has(k)) return E('#CYCLE!')
  active.add(k)
  const v = evalCell(cell)
  active.delete(k)
  memo.set(k, v)
  return v
}

function evalCell(cell) {
  const c = cell.content
  if (c[0] === '=') return cell.bad ? E('#ERR!') : ev(cell.ast)
  if (c === '') return N(0)
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(c)) return N(Number(c))
  if (ERRS.includes(c)) return E(c)
  return { t: 's', v: c }
}

function toNum(x) {
  if (x.t === 'n') return x
  if (x.t === 'b') return N(x.v ? 1 : 0)
  if (x.t === 'e') return x
  return E('#VALUE!')
}
const fin = (v) => (Number.isFinite(v) ? N(v) : E('#DIV/0!'))
const rank = { n: 0, s: 1, b: 2 }
function cmp(x, y) {
  if (x.t !== y.t) return rank[x.t] - rank[y.t]
  if (x.t === 's') {
    const a = Array.from(x.v), b = Array.from(y.v)
    for (let i = 0; i < Math.min(a.length, b.length); i++) {
      const d = a[i].codePointAt(0) - b[i].codePointAt(0)
      if (d) return d
    }
    return a.length - b.length
  }
  return Number(x.v) - Number(y.v)
}

function ev(e) {
  switch (e.n) {
    case 'num': return N(e.v)
    case 'bool': return { t: 'b', v: e.v }
    case 'ref': { const a = parseAddr(e.w); return a ? cellValue(a) : E('#REF!') }
    case 'range': return E('#ERR!')
    case 'un': {
      const x = toNum(ev(e.x))
      if (isErr(x)) return x
      return N(e.op === '-' ? -x.v : x.v)
    }
    case 'bin': {
      const l = ev(e.l)
      if (isErr(l)) return l
      const r = ev(e.r)
      if (isErr(r)) return r
      if (['=', '<>', '<', '<=', '>', '>='].includes(e.op)) {
        const d = cmp(l, r)
        const v = { '=': d === 0, '<>': d !== 0, '<': d < 0, '<=': d <= 0, '>': d > 0, '>=': d >= 0 }[e.op]
        return { t: 'b', v }
      }
      const a = toNum(l)
      if (isErr(a)) return a
      const b = toNum(r)
      if (isErr(b)) return b
      switch (e.op) {
        case '+': return fin(a.v + b.v)
        case '-': return fin(a.v - b.v)
        case '*': return fin(a.v * b.v)
        case '/': return b.v === 0 ? E('#DIV/0!') : fin(a.v / b.v)
        case '^': return fin(Math.pow(a.v, b.v))
      }
      return E('#ERR!')
    }
    case 'call': return call(e)
  }
  return E('#ERR!')
}

function call(e) {
  const { name, args } = e
  if (name === 'IF') {
    if (args.length !== 3 || args.some((a) => a.n === 'range')) return E('#ERR!')
    const c = ev(args[0])
    if (isErr(c)) return c
    let t
    if (c.t === 'b') t = c.v
    else if (c.t === 'n') t = c.v !== 0
    else return E('#VALUE!')
    return ev(args[t ? 1 : 2])
  }
  if (name === 'ABS') {
    if (args.length !== 1 || args[0].n === 'range') return E('#ERR!')
    const x = toNum(ev(args[0]))
    return isErr(x) ? x : N(Math.abs(x.v))
  }
  if (!['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'].includes(name)) return E('#NAME?')
  if (args.length < 1) return E('#ERR!')
  const vals = []
  for (const a of args) {
    if (a.n === 'range') {
      const cs = rangeCells(a)
      if (!cs) vals.push(E('#REF!'))
      else for (const c of cs) vals.push(cellValue(c))
    } else vals.push(ev(a))
  }
  const firstErr = vals.find(isErr)
  if (firstErr) return firstErr
  if (name === 'COUNT') return N(vals.filter((v) => v.t === 'n').length)
  const nums = []
  for (const v of vals) {
    const x = toNum(v)
    if (isErr(x)) return x
    nums.push(x.v)
  }
  if (name === 'MIN') return N(Math.min(...nums))
  if (name === 'MAX') return N(Math.max(...nums))
  const sum = nums.reduce((s, x) => s + x, 0)
  return name === 'SUM' ? fin(sum) : fin(sum / nums.length)
}

function fmt(v) {
  switch (v.t) {
    case 'n': return String(Number(v.v.toPrecision(10)))
    case 'e': return v.v
    case 'b': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}

const sorted = [...cells.values()].sort((x, y) => key(x.a) - key(y.a))
process.stdout.write(sorted.map((c) => `${colName(c.a.c)}${c.a.r}=${fmt(cellValue(c.a))}\n`).join(''))
EOF
