const fail = (msg) => Object.assign(new Error(msg), { parseError: true })
const isWs = (c) => c === ' ' || c === '\t'
const isBare = (c) => c !== undefined && /[A-Za-z0-9_-]/.test(c)
const D = '\\d+(?:_\\d+)*'
const INT = new RegExp(`^[+-]?${D}$`)
const FLOAT = new RegExp(`^[+-]?${D}(?:\\.${D})?(?:[eE][+-]?${D})?$`)
const mkTable = () => ({ t: 'table', map: new Map(), header: false })

class Line {
  constructor(s) { this.s = s; this.i = 0 }
  ws() { while (isWs(this.s[this.i])) this.i++ }
  atEnd() { const c = this.s[this.i]; return c === undefined || c === '#' || c === ';' }

  basic() {
    const s = this.s
    let out = ''
    this.i++
    for (;;) {
      const c = s[this.i]
      if (c === undefined) throw fail('unterminated string')
      if (c === '"') { this.i++; return out }
      if (c !== '\\') { out += c; this.i++; continue }
      const e = s[this.i + 1]
      if (e === undefined) throw fail('unterminated string')
      const map = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
      if (Object.hasOwn(map, e)) { out += map[e]; this.i += 2 }
      else if (e === 'u') {
        const h = s.slice(this.i + 2, this.i + 6)
        if (!/^[0-9A-Fa-f]{4}$/.test(h)) throw fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16)); this.i += 6
      } else throw fail(`invalid escape \\${String.fromCodePoint(s.codePointAt(this.i + 1))}`)
    }
  }
  literal() {
    const j = this.s.indexOf("'", this.i + 1)
    if (j < 0) throw fail('unterminated string')
    const v = this.s.slice(this.i + 1, j)
    this.i = j + 1
    return v
  }
  name() {
    const c = this.s[this.i]
    if (c === '"') return this.basic()
    if (c === "'") return this.literal()
    if (!isBare(c)) throw fail('expected a name')
    const st = this.i
    while (isBare(this.s[this.i])) this.i++
    return this.s.slice(st, this.i)
  }
  dotted() {
    const parts = []
    this.ws()
    parts.push(this.name())
    for (;;) {
      this.ws()
      if (this.s[this.i] !== '.') return parts
      this.i++
      this.ws()
      parts.push(this.name())
    }
  }

  value(prefix) {
    this.ws()
    const c = this.s[this.i]
    if (this.atEnd() || c === ',' || c === ']' || c === '}') throw fail('expected a value')
    if (c === '"') return { t: 'string', v: this.basic() }
    if (c === "'") return { t: 'string', v: this.literal() }
    if (c === '[') {
      this.i++
      const items = []
      this.ws()
      if (this.s[this.i] === ']') { this.i++; return { t: 'array', items, aot: false } }
      for (;;) {
        items.push(this.value(prefix))
        this.ws()
        const d = this.s[this.i]
        if (d === ',') {
          this.i++
          this.ws()
          if (this.s[this.i] === ']') { this.i++; break }
        } else if (d === ']') { this.i++; break }
        else throw fail('unterminated array')
      }
      return { t: 'array', items, aot: false }
    }
    if (c === '{') {
      this.i++
      const tbl = mkTable()
      this.ws()
      if (this.s[this.i] === '}') { this.i++; return tbl }
      for (;;) {
        const keys = this.dotted()
        if (this.s[this.i] !== '=') throw fail('expected = in an inline table')
        this.i++
        const v = this.value([...prefix, ...keys])
        assign(tbl, prefix, keys, v)
        this.ws()
        const d = this.s[this.i]
        if (d === ',') { this.i++; this.ws() }
        else if (d === '}') { this.i++; return tbl }
        else throw fail('unterminated inline table')
      }
    }
    const st = this.i
    while (this.s[this.i] !== undefined && !isWs(this.s[this.i]) && !',]}'.includes(this.s[this.i])) this.i++
    const w = this.s.slice(st, this.i)
    if (w === 'true' || w === 'false') return { t: 'boolean', v: w === 'true' }
    if (INT.test(w)) return { t: 'integer', v: BigInt(w.replace(/_/g, '')) }
    if (FLOAT.test(w)) return { t: 'float', v: Number(w.replace(/_/g, '')) }
    throw fail(`invalid value ${w}`)
  }
}

// Walk (creating tables) from `tbl` along `keys`; returns the table reached.
function walk(tbl, base, keys) {
  let cur = tbl
  keys.forEach((k, idx) => {
    const path = [...base, ...keys.slice(0, idx + 1)].join('.')
    let n = cur.map.get(k)
    if (!n) { n = mkTable(); cur.map.set(k, n) }
    if (n.t === 'array' && n.aot) n = n.items[n.items.length - 1]
    else if (n.t !== 'table') throw fail(`${path} is not a table`)
    cur = n
  })
  return cur
}

function assign(tbl, base, keys, v) {
  const t = walk(tbl, base, keys.slice(0, -1))
  const last = keys[keys.length - 1]
  if (t.map.has(last)) throw fail(`key ${[...base, ...keys].join('.')} is defined twice`)
  t.map.set(last, v)
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = mkTable()
  let cur = root
  let curPath = []
  lines.forEach((raw, idx) => {
    try {
      const L = new Line(raw)
      L.ws()
      if (L.atEnd()) return
      if (raw[L.i] === '[') {
        L.i++
        const dbl = raw[L.i] === '['
        if (dbl) L.i++
        const keys = L.dotted()
        const close = (ch) => { if (raw[L.i] !== ch) throw fail('unterminated table header'); L.i++ }
        close(']')
        if (dbl) close(']')
        L.ws()
        if (!L.atEnd()) throw fail('trailing text after a table header')
        const parent = walk(root, [], keys.slice(0, -1))
        const last = keys[keys.length - 1]
        const full = keys.join('.')
        const n = parent.map.get(last)
        if (dbl) {
          if (!n) {
            const t = mkTable(); t.header = true
            parent.map.set(last, { t: 'array', items: [t], aot: true })
            cur = t
          } else if (n.t === 'array' && n.aot) {
            const t = mkTable(); t.header = true
            n.items.push(t)
            cur = t
          } else throw fail(`${full} is not an array of tables`)
        } else if (!n) {
          const t = mkTable(); t.header = true
          parent.map.set(last, t)
          cur = t
        } else if (n.t !== 'table') throw fail(`${full} is not a table`)
        else if (n.header) throw fail(`table ${full} is defined twice`)
        else { n.header = true; cur = n }
        curPath = keys
        return
      }
      const keys = L.dotted()
      if (raw[L.i] !== '=') throw fail('expected key = value')
      L.i++
      const v = L.value(curPath.concat(keys))
      L.ws()
      if (!L.atEnd()) throw fail('trailing text after a value')
      assign(cur, curPath, keys, v)
    } catch (e) {
      if (e.parseError) e.message = `line ${idx + 1}: ${e.message}`
      throw e
    }
  })
  return root
}
