import { GraphError } from './graph.js'

/** Detects cycles, then computes start/finish/depth per task. */
export function schedule({ names, costs, deps }) {
  const state = new Map()
  const stack = []
  const info = new Map()
  const visit = (n) => {
    state.set(n, 1)
    stack.push(n)
    let start = 0n
    let depth = 0
    for (const d of deps.get(n)) {
      const s = state.get(d)
      if (s === 1) {
        const cyc = stack.slice(stack.indexOf(d))
        cyc.push(d)
        throw new GraphError(`error: cycle: ${cyc.join(' -> ')}`, 3)
      }
      if (s !== 2) visit(d)
      const di = info.get(d)
      if (di.finish > start) start = di.finish
      if (di.depth + 1 > depth) depth = di.depth + 1
    }
    stack.pop()
    state.set(n, 2)
    info.set(n, { start, finish: start + costs.get(n), depth })
  }
  for (const n of names) if (!state.has(n)) visit(n)
  return info
}

