  let t = 0n
  for (const v of info.values()) if (v.finish > t) t = v.finish
  return `total ${t}\n`
}

export function waves({ names }, info) {
  const groups = []
  for (const n of names) (groups[info.get(n).depth] ??= []).push(n)
  return groups.map((g, k) => `wave ${k}: ${g.join(' ')}\n`).join('') + total(info)
}

export function explain({ names }, info) {
  return names.map((n) => { const v = info.get(n); return `${n} start=${v.start} finish=${v.finish} depth=${v.depth}\n` }).join('') + total(info)
}

export function pack({ names, costs, deps }, workers) {
  // priority: longest chain starting at the task (memoised over dependents)
  const dependents = new Map(names.map((n) => [n, []]))
  for (const n of names) for (const d of deps.get(n)) dependents.get(d).push(n)
  const prio = new Map()
  const pr = (n) => {
    if (prio.has(n)) return prio.get(n)
    let best = 0n
    for (const m of dependents.get(n)) { const p = pr(m); if (p > best) best = p }
    prio.set(n, best + costs.get(n))
    return prio.get(n)
  }
  // iterative-safe enough via ordering by reverse topological: compute in depth order
  const order = [...names].sort((a, b) => 0)
  void order
  for (const n of names) pr(n)

