  let t = 0n
  let makespan = 0n
  while (pending.size > 0) {
    for (;;) {
      const w = freeAt.findIndex((f) => f <= t)
      if (w < 0) break
      let pick = null
      for (const n of pending) {
        if (!deps.get(n).every((d) => finish.has(d) && finish.get(d) <= t)) continue
        if (pick === null || prio.get(n) > prio.get(pick) || (prio.get(n) === prio.get(pick) && n < pick)) pick = n
      }
      if (pick === null) break
      pending.delete(pick)
      const f = t + costs.get(pick)
      finish.set(pick, f)
      freeAt[w] = f
      if (f > makespan) makespan = f
      ran[w].push(`${pick}@${t}-${f}`)
    }
    if (pending.size === 0) break
    let next = null
    for (const f of freeAt) if (f > t && (next === null || f < next)) next = f
    if (next === null) break
    t = next
  }
  return ran.map((r, i) => `worker ${i}:${r.map((x) => ' ' + x).join('')}\n`).join('') + `makespan ${makespan}\n`
}
