    if (c === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') adv()
      continue
    }
    if (c === '/' && cs[i + 1] === '*') {
      let depth = 0
      while (i < n) {
        if (cs[i] === '/' && cs[i + 1] === '*') { adv(); adv(); depth++ }
        else if (cs[i] === '*' && cs[i + 1] === '/') { adv(); adv(); depth--; if (depth === 0) break }
        else adv()
      }
      if (depth > 0) throw new ScanError(sl, sc, 'unterminated block comment')
      continue
    }
    if (c === 'r' && cs[i + 1] === '"') {
      adv(); adv()
      let v = ''
      for (;;) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const d = adv()
        if (d === '"') break
        v += d
      }
      tokens.push([sl, sc, 'rawstring', JSON.stringify(v)])
      continue
    }
    if (isIdStart(c)) {
      while (i < n && isIdChar(cs[i])) adv()
      const w = cs.slice(start, i).join('')
      tokens.push([sl, sc, KEYWORDS.has(w) ? 'keyword' : 'ident', w])
      continue
    }
    if (isDigit(c)) {
      let bad = false
      const p = cs[i + 1]
      const prefixes = { x: isHex, X: isHex, b: (d) => d === '0' || d === '1', B: (d) => d === '0' || d === '1', o: (d) => d >= '0' && d <= '7' && d.length === 1, O: (d) => d >= '0' && d <= '7' && d.length === 1 }
