{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */
import { readFileSync } from 'node:fs'
import { parse, ParseError } from './parse.js'
import { simulate } from './sim.js'

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'replay' && args[0] !== 'summary')) {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

let out
try {
  const { policies, routes, events } = parse(readFileSync(0, 'utf8'))
  const results = simulate(policies, routes, events)
  out = ''
  if (args[0] === 'replay') {
    for (const r of results) out += `${r.tick} ${r.key} ${r.denied === null ? 'allow' : 'deny ' + r.denied}\n`
  } else {
    const per = new Map()
    let a = 0
    let d = 0
    for (const r of results) {
      const c = per.get(r.key) ?? { a: 0, d: 0 }
      if (r.denied === null) { c.a++; a++ } else { c.d++; d++ }
      per.set(r.key, c)
    }
    for (const k of [...per.keys()].sort((x, y) => (x < y ? -1 : x > y ? 1 : 0))) {
      out += `${k} allowed=${per.get(k).a} denied=${per.get(k).d}\n`
    }
    out += `total allowed=${a} denied=${d}\n`
  }
} catch (e) {
  if (!(e instanceof ParseError)) throw e
  process.stderr.write(`error: line ${e.line}: ${e.message}\n`)
  process.exit(2)
}
process.stdout.write(out)
"}

{"file_path":"src/parse.js","content":"export class ParseError extends Error {
  constructor(line, message) {
    super(message)
    this.line = line
  }
}

const WORD = /^[A-Za-z0-9_./:-]+$/
const COUNT = /^(0|[1-9][0-9]*)$/

export function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let lastTick = null

  lines.forEach((raw, i) => {
    const n = i + 1
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const t = line.split(/\s+/)
    const fail = (m) => { throw new ParseError(n, m) }
    const num = (field, v, least) => {
      if (!COUNT.test(v) || BigInt(v) < BigInt(least)) fail(`${field} must be an integer of at least ${least}`)
      return BigInt(v)
    }
    const word = t[0]
    if (word !== 'bucket' && word !== 'window' && word !== 'route' && word !== 'event') {
      fail(`unknown directive ${word}`)
    }
    if (word !== 'event' && events.length > 0) fail('declarations must come before the first event')
    if (word === 'bucket') {
      if (t.length !== 5) fail('expected bucket <name> <capacity> <refill> <per>')
      if (!WORD.test(t[1])) fail(`invalid policy name ${t[1]}`)
      const capacity = num('capacity', t[2], 1)
      const refill = num('refill', t[3], 0)
      const per = num('per', t[4], 1)
      if (policies.has(t[1])) fail(`policy ${t[1]} is declared twice`)
      policies.set(t[1], { kind: 'bucket', name: t[1], capacity, refill, per })
    } else if (word === 'window') {
