function makeState(p, tick) {
  if (p.kind === 'bucket') return { tokens: p.capacity * p.per, last: tick }
  return { ticks: [] }
}

function advance(p, s, tick) {
  if (p.kind === 'bucket') {
    const max = p.capacity * p.per
    s.tokens += p.refill * (tick - s.last)
    if (s.tokens > max) s.tokens = max
    s.last = tick
  } else {
    const cut = tick - p.span
    s.ticks = s.ticks.filter((t) => t > cut)
  }
}

function allows(p, s) {
  return p.kind === 'bucket' ? s.tokens >= p.per : BigInt(s.ticks.length) < p.limit
}

function record(p, s, tick) {
  if (p.kind === 'bucket') s.tokens -= p.per
  else s.ticks.push(tick)
}

export function simulate(policies, routes, events) {
  const prefixes = [...routes.keys()].sort((a, b) => b.length - a.length)
  const states = new Map()
  const results = []
  for (const { tick, key } of events) {
    const prefix = prefixes.find((x) => key.startsWith(x))
    let denied = null
    if (prefix !== undefined) {
      const list = routes.get(prefix).map((name) => {
        const p = policies.get(name)
        const id = `${name}\0${key}`
        let s = states.get(id)
        if (!s) states.set(id, (s = makeState(p, tick)))
        return [p, s]
      })
      for (const [p, s] of list) advance(p, s, tick)
      for (const [p, s] of list) {
        if (!allows(p, s)) { denied = p.name; break }
      }
      if (denied === null) for (const [p, s] of list) record(p, s, tick)
    }
    results.push({ tick, key, denied })
  }
  return results
}
"}

