{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}
if (mode !== 'rounds' && mode !== 'tally') fail('error: usage: cli.js rounds|tally')

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

let cands = null
const ballots = []
let seenBallot = false
for (let i = 0; i < lines.length; i++) {
  const n = i + 1
  const t = lines[i].trim()
  if (t === '' || t.startsWith('#')) continue
  const w = t.split(/\s+/)
  if (w[0] === 'candidates') {
    if (cands !== null || seenBallot) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (w.length < 2) fail(`error: line ${n}: expected candidates <name>...`)
    const seen = new Set()
    for (const name of w.slice(1)) {
      if (!/^[A-Za-z0-9_-]+$/.test(name)) fail(`error: line ${n}: invalid candidate name ${name}`)
      if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is declared twice`)
      seen.add(name)
    }
    cands = w.slice(1)
  } else if (w[0] === 'ballot') {
    if (cands === null) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    seenBallot = true
    if (w.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
    if (!/^[1-9][0-9]*$/.test(w[1])) fail(`error: line ${n}: count must be a positive integer`)
    const seen = new Set()
    for (const name of w.slice(2)) {
      if (!cands.includes(name)) fail(`error: line ${n}: unknown candidate ${name}`)
      if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is repeated`)
      seen.add(name)
    }
    ballots.push({ count: BigInt(w[1]), prefs: w.slice(2) })
  } else {
    fail(`error: line ${n}: unknown directive ${w[0]}`)
  }
}
if (cands === null) fail('error: no candidates')

const cont = new Set(cands)
const history = new Map(cands.map((c) => [c, []]))
const out = []
let rounds = 0
let winner = null
for (;;) {
  rounds++
  const counts = new Map([...cont].map((c) => [c, 0n]))
  let active = 0n
  for (const b of ballots) {
    const c = b.prefs.find((p) => cont.has(p))
    if (c !== undefined) {
      counts.set(c, counts.get(c) + b.count)
      active += b.count
    }
  }
  for (const [c, v] of counts) history.get(c).push(v)
  const exhausted = ballots.reduce((s, b) => s + b.count, 0n) - active
  const listed = [...counts].sort((a, b) => (a[1] === b[1] ? (a[0] < b[0] ? -1 : 1) : a[1] > b[1] ? -1 : 1))
  out.push(`round ${rounds}: ${listed.map(([c, v]) => `${c}=${v}`).join(' ')} exhausted=${exhausted}`)
  if (active === 0n) break
  const top = listed.find(([, v]) => v * 2n > active)
  if (top) {
    winner = top[0]
    break
  }
  let min = null
  for (const v of counts.values()) if (min === null || v < min) min = v
  let set = [...counts].filter(([, v]) => v === min).map(([c]) => c)
  for (let r = 0; r < rounds && set.length > 1; r++) {
    let m = null
    for (const c of set) { const v = history.get(c)[r]; if (m === null || v < m) m = v }
    const keep = set.filter((c) => history.get(c)[r] === m)
    if (keep.length < set.length) { set = keep; r = -1 }
  }
  set.sort()
  const elim = set[set.length - 1]
  cont.delete(elim)
  out.push(`eliminated ${elim}`)
}
const end = winner === null ? 'no winner' : `winner ${winner}`
if (mode === 'rounds') process.stdout.write(out.join('\n') + '\n' + end + '\n')
else process.stdout.write(`rounds ${rounds}\n${end}\n`)
EOF
