{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

const WORD = /^[A-Za-z0-9_./:-]+$/
const UINT = /^(0|[1-9][0-9]*)$/
class Fail extends Error {}

function parse(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let lastTick = null
  const int = (v, field, least) => {
    if (!UINT.test(v) || BigInt(v) < BigInt(least)) throw new Fail(`${field} must be an integer of at least ${least}`)
    return BigInt(v)
  }
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const f = line.split(/\s+/)
    const d = f[0]
    try {
      if (d === 'bucket' || d === 'window' || d === 'route' || d === 'event') {
        const need = { bucket: [5, 5], window: [4, 4], route: [3, Infinity], event: [3, 3] }[d]
        const usage = {
          bucket: 'expected bucket <name> <capacity> <refill> <per>',
          window: 'expected window <name> <limit> <span>',
          route: 'expected route <prefix> <policy>...',
          event: 'expected event <tick> <key>',
        }[d]
        if (f.length < need[0] || f.length > need[1]) throw new Fail(usage)
        if (d !== 'event' && events.length) throw new Fail('declarations must come before the first event')
        if (d === 'bucket' || d === 'window') {
          if (!WORD.test(f[1])) throw new Fail(`invalid policy name ${f[1]}`)
          if (policies.has(f[1])) throw new Fail(`policy ${f[1]} is declared twice`)
          if (d === 'bucket') {
            const capacity = int(f[2], 'capacity', 1)
            const refill = int(f[3], 'refill', 0)
            const per = int(f[4], 'per', 1)
            policies.set(f[1], { name: f[1], kind: 'bucket', capacity, refill, per })
          } else {
            const limit = int(f[2], 'limit', 0)
            const span = int(f[3], 'span', 1)
            policies.set(f[1], { name: f[1], kind: 'window', limit, span })
          }
        } else if (d === 'route') {
          if (!WORD.test(f[1])) throw new Fail(`invalid route prefix ${f[1]}`)
          if (routes.has(f[1])) throw new Fail(`prefix ${f[1]} is routed twice`)
          const ps = []
          for (const n of f.slice(2)) {
            if (!policies.has(n)) throw new Fail(`unknown policy ${n}`)
            ps.push(policies.get(n))
          }
          routes.set(f[1], ps)
        } else {
          const tick = int(f[1], 'tick', 0)
          if (!WORD.test(f[2])) throw new Fail(`invalid key ${f[2]}`)
          if (lastTick !== null && tick < lastTick) throw new Fail(`tick ${tick} is before tick ${lastTick}`)
          lastTick = tick
          events.push({ tick, key: f[2] })
        }
      } else throw new Fail(`unknown directive ${d}`)
    } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${i + 1}: ${e.message}`)
      throw e
    }
  }
  return { routes, events }
}

function run({ routes, events }) {
  const states = new Map()
  const stateFor = (p, key) => {
    const id = p.name + '\0' + key
    let s = states.get(id)
    if (!s) {
      s = p.kind === 'bucket' ? { num: p.capacity * p.per, last: null } : { ticks: [] }
      states.set(id, s)
    }
    return s
  }
  const res = []
  for (const ev of events) {
    let best = null
    for (const pre of routes.keys()) {
      if (ev.key.startsWith(pre) && (best === null || pre.length > best.length)) best = pre
    }
    const ps = best === null ? [] : routes.get(best)
    const sts = ps.map((p) => stateFor(p, ev.key))
    ps.forEach((p, i) => {
      const s = sts[i]
      if (p.kind === 'bucket') {
        if (s.last !== null) {
          s.num += p.refill * (ev.tick - s.last)
          const cap = p.capacity * p.per
          if (s.num > cap) s.num = cap
        }
        s.last = ev.tick
      } else {
        const cut = ev.tick - p.span
        s.ticks = s.ticks.filter((t) => t > cut)
      }
    })
    let denied = null
    for (let i = 0; i < ps.length; i++) {
      const p = ps[i]
      const s = sts[i]
      const ok = p.kind === 'bucket' ? s.num >= p.per : BigInt(s.ticks.length) < p.limit
      if (!ok) { denied = p.name; break }
    }
    if (denied === null) {
      ps.forEach((p, i) => {
        if (p.kind === 'bucket') sts[i].num -= p.per
        else sts[i].ticks.push(ev.tick)
      })
    }
    res.push({ tick: ev.tick, key: ev.key, denied })
  }
  return res
}

let parsed
try {
  parsed = parse(readFileSync(0, 'utf8'))
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
const results = run(parsed)
let out = ''
if (mode === 'replay') {
  for (const r of results) out += `${r.tick} ${r.key} ${r.denied === null ? 'allow' : 'deny ' + r.denied}\n`
} else {
  const m = new Map()
  let ta = 0, td = 0
  for (const r of results) {
    const c = m.get(r.key) || { a: 0, d: 0 }
    if (r.denied === null) { c.a++; ta++ } else { c.d++; td++ }
    m.set(r.key, c)
  }
  for (const k of [...m.keys()].sort((x, y) => (x < y ? -1 : x > y ? 1 : 0))) out += `${k} allowed=${m.get(k).a} denied=${m.get(k).d}\n`
  out += `total allowed=${ta} denied=${td}\n`
}
process.stdout.write(out)
EOF
