const ERRS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const err = (code) => ({ k: 'e', v: code })
const num = (v) => ({ k: 'n', v })
const isErr = (x) => x.k === 'e'

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) fail('error: usage: cli.js values|deps')
const mode = args[0]

// ---------- addresses ----------
function parseAddr(w) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(w)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const L = m[1].toUpperCase()
  const col = L.length === 1 ? L.charCodeAt(0) - 64 : (L.charCodeAt(0) - 64) * 26 + L.charCodeAt(1) - 64
  return { col, row }
}
const colName = (c) => (c <= 26 ? String.fromCharCode(64 + c) : String.fromCharCode(64 + Math.floor((c - 1) / 26)) + String.fromCharCode(65 + ((c - 1) % 26)))
const key = (col, row) => col * 1000 + row
const addrStr = (k) => colName(Math.floor(k / 1000)) + (k % 1000)

// ---------- read sheet ----------
const input = readFileSync(0, 'utf8')
const lines = input.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()
