        return { k: 'b', v: r }
      }
      const l = toNum(L)
      if (isErr(l)) return l
      const r = toNum(evalNode(n.r))
      if (isErr(r)) return r
      switch (n.op) {
        case '+': return finite(l.v + r.v)
        case '-': return finite(l.v - r.v)
        case '*': return finite(l.v * r.v)
        case '/': return r.v === 0 ? err('#DIV/0!') : finite(l.v / r.v)
        case '^': return finite(Math.pow(l.v, r.v))
      }
      return err('#ERR!')
    }
    case 'call': return evalCall(n)
  }
  return err('#ERR!')
}

function evalCall(n) {
  const name = n.name
  const cnt = n.args.length
  if (name === 'IF') {
    if (cnt !== 3) return err('#ERR!')
    const c = scalar(n.args[0])
    if (isErr(c)) return c
    let truth
    if (c.k === 'b') truth = c.v
    else if (c.k === 'n') truth = c.v !== 0
    else return err('#VALUE!')
    return scalar(n.args[truth ? 1 : 2])
  }
  if (name === 'ABS') {
    if (cnt !== 1) return err('#ERR!')
    const x = toNum(scalar(n.args[0]))
    if (isErr(x)) return x
    return num(Math.abs(x.v))
  }
  if (!['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'].includes(name)) return err('#NAME?')
  if (cnt < 1) return err('#ERR!')
