    case 'SUM': return finite(nums.reduce((a, b) => a + b, 0))
    case 'MIN': return num(Math.min(...nums))
    case 'MAX': return num(Math.max(...nums))
    case 'AVG': return finite(nums.reduce((a, b) => a + b, 0) / nums.length)
  }
  return err('#ERR!')
}

function show(v) {
  if (v.k === 'e' || v.k === 't') return v.v
  if (v.k === 'b') return v.v ? 'TRUE' : 'FALSE'
  return String(Number(v.v.toPrecision(10)))
}

// ---------- output ----------
const keys = [...cells.keys()].sort((a, b) => a - b)
const out = []
for (const k of keys) {
  if (mode === 'values') out.push(`${addrStr(k)}=${show(cellValue(k))}`)
  else {
    const set = new Set()
    const f = info.get(k).formula
    if (f) collect(f.ast, set)
    out.push(`${addrStr(k)}:` + [...set].sort((a, b) => a - b).map((d) => ' ' + addrStr(d)).join(''))
  }
}
process.stdout.write(out.length ? out.join('\n') + '\n' : '')
"}

