  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(w)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const L = m[1].toUpperCase()
  const col = L.length === 1 ? L.charCodeAt(0) - 64 : (L.charCodeAt(0) - 64) * 26 + L.charCodeAt(1) - 64
  return { col, row }
}
const colName = (c) => (c <= 26 ? String.fromCharCode(64 + c) : String.fromCharCode(64 + Math.floor((c - 1) / 26)) + String.fromCharCode(65 + ((c - 1) % 26)))
const key = (col, row) => col * 1000 + row
const addrStr = (k) => colName(Math.floor(k / 1000)) + (k % 1000)

// ---------- read sheet ----------
const input = readFileSync(0, 'utf8')
const lines = input.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()
const cells = new Map()
lines.forEach((raw, i) => {
  const s = raw.replace(/^[ \t]+/, '')
  if (s === '' || s[0] === '#') return
  const m = /^([^ \t]*)[ \t]*([\s\S]*)$/.exec(s)
  const addr = m[1]
  const a = parseAddr(addr)
  if (!a) fail(`error: line ${i + 1}: invalid cell address ${addr}`)
  const k = key(a.col, a.row)
  if (cells.has(k)) fail(`error: line ${i + 1}: cell ${addr} is declared twice`)
  cells.set(k, m[2])
})

// ---------- formula parser ----------
function lex(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const c = s[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) { toks.push({ t: 'num', v: Number(m[0]) }); i += m[0].length; continue }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) { toks.push({ t: 'word', v: m[0] }); i += m[0].length; continue }
    if ((m = /^(<>|<=|>=|[<>=^*\/+\-(),:])/.exec(s.slice(i)))) { toks.push({ t: 'op', v: m[0] }); i += m[0].length; continue }
    return null
  }
  return toks
}

function parseFormula(body) {
  const toks = lex(body)
  if (!toks) return null
  let p = 0
  let rangesSeen = 0
  const peek = () => toks[p]
  const isOp = (v) => p < toks.length && toks[p].t === 'op' && toks[p].v === v
  const bad = () => { throw new SyntaxError() }

  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].t === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { n: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) { const op = toks[p++].v; l = { n: 'bin', op, l, r: mul() } }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) { const op = toks[p++].v; l = { n: 'bin', op, l, r: pow() } }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { n: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) { const op = toks[p++].v; return { n: 'un', op, x: unary() } }
    return primary()
  }
  function primary() {
    const t = peek()
    if (!t) bad()
    if (t.t === 'num') { p++; return { n: 'num', v: t.v } }
    if (t.t === 'op' && t.v === '(') {
      p++
      const e = cmp()
      if (!isOp(')')) bad()
      p++
      return e
    }
    if (t.t === 'word') {
      p++
      if (isOp('(')) {
        p++
        const argv = []
        if (isOp(')')) bad()
        for (;;) {
          const e = cmp()
          if (e.n === 'range') rangesSeen--
          argv.push(e)
          if (isOp(',')) { p++; continue }
          if (isOp(')')) { p++; break }
          bad()
        }
        return { n: 'call', name: t.v.toUpperCase(), args: argv }
      }
      if (isOp(':')) {
        p++
        const t2 = peek()
        if (!t2 || t2.t !== 'word') bad()
        p++
        rangesSeen++
        return { n: 'range', a: t.v, b: t2.v }
      }
      const u = t.v.toUpperCase()
      if (u === 'TRUE') return { n: 'bool', v: true }
      if (u === 'FALSE') return { n: 'bool', v: false }
      return { n: 'ref', w: t.v }
    }
    bad()
  }
  try {
    const e = cmp()
    if (p !== toks.length) return null
    return { ast: e, misplaced: rangesSeen > 0 }
  } catch (x) {
    if (x instanceof SyntaxError) return null
    throw x
  }
}

// ---------- parse every cell ----------
const info = new Map()
for (const [k, content] of cells) {
  if (content[0] === '=') info.set(k, { formula: parseFormula(content.slice(1)) })
  else info.set(k, { formula: undefined })
}

function rangeKeys(a, b) {
  const A = parseAddr(a), B = parseAddr(b)
  if (!A || !B) return null
  const out = []
  for (let c = Math.min(A.col, B.col); c <= Math.max(A.col, B.col); c++)
    for (let r = Math.min(A.row, B.row); r <= Math.max(A.row, B.row); r++) out.push(key(c, r))
  return out
}

// ---------- deps ----------
function collect(n, set) {
  switch (n.n) {
    case 'ref': { const a = parseAddr(n.w); if (a) set.add(key(a.col, a.row)); break }
    case 'range': { const ks = rangeKeys(n.a, n.b); if (ks) ks.forEach((k) => set.add(k)); break }
    case 'bin': collect(n.l, set); collect(n.r, set); break
    case 'un': collect(n.x, set); break
    case 'call': n.args.forEach((a) => collect(a, set)); break
  }
}

// ---------- evaluation ----------
const memo = new Map()
const busy = new Set()

function cellValue(k) {
  if (memo.has(k)) return memo.get(k)
  if (busy.has(k)) return err('#CYCLE!')
  if (!cells.has(k)) return num(0)
  const content = cells.get(k)
  let v
  if (content[0] === '=') {
    busy.add(k)
    const f = info.get(k).formula
    if (!f || f.misplaced) v = err('#ERR!')
    else v = evalNode(f.ast)
    busy.delete(k)
  } else if (content === '') v = num(0)
  else if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) v = num(Number(content))
  else if (ERRS.includes(content)) v = err(content)
  else v = { k: 't', v: content }
  memo.set(k, v)
  return v
}

function toNum(x) {
  if (x.k === 'n') return x
  if (x.k === 'b') return num(x.v ? 1 : 0)
  if (x.k === 't') return err('#VALUE!')
  return x
}
function finite(v) {
  return Number.isFinite(v) ? num(v) : err('#DIV/0!')
}
const rank = { n: 0, t: 1, b: 2 }
function compare(a, b) {
  if (a.k !== b.k) return rank[a.k] - rank[b.k]
  if (a.k === 't') return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
  const x = a.k === 'b' ? Number(a.v) : a.v
  const y = b.k === 'b' ? Number(b.v) : b.v
  return x < y ? -1 : x > y ? 1 : 0
}

function argValues(a) {
  if (a.n === 'range') {
    const ks = rangeKeys(a.a, a.b)
    if (!ks) return [err('#REF!')]
    return ks.map(cellValue)
  }
  return [evalNode(a)]
}
function scalar(a) {
  const vs = argValues(a)
  return vs.length === 1 ? vs[0] : err('#ERR!')
}

function evalNode(n) {
  switch (n.n) {
    case 'num': return num(n.v)
    case 'bool': return { k: 'b', v: n.v }
    case 'ref': {
      const a = parseAddr(n.w)
      return a ? cellValue(key(a.col, a.row)) : err('#REF!')
    }
    case 'range': return err('#ERR!')
    case 'un': {
      const x = toNum(evalNode(n.x))
      if (isErr(x)) return x
      return num(n.op === '-' ? -x.v : x.v)
    }
    case 'bin': {
      const L = evalNode(n.l)
      if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
        if (isErr(L)) return L
        const R = evalNode(n.r)
        if (isErr(R)) return R
        const c = compare(L, R)
        const r = { '=': c === 0, '<>': c !== 0, '<': c < 0, '<=': c <= 0, '>': c > 0, '>=': c >= 0 }[n.op]
        return { k: 'b', v: r }
      }
      const l = toNum(L)
      if (isErr(l)) return l
      const r = toNum(evalNode(n.r))
      if (isErr(r)) return r
      switch (n.op) {
        case '+': return finite(l.v + r.v)
        case '-': return finite(l.v - r.v)
        case '*': return finite(l.v * r.v)
        case '/': return r.v === 0 ? err('#DIV/0!') : finite(l.v / r.v)
        case '^': return finite(Math.pow(l.v, r.v))
      }
      return err('#ERR!')
    }
    case 'call': return evalCall(n)
  }
  return err('#ERR!')
}

function evalCall(n) {
  const name = n.name
  const cnt = n.args.length
  if (name === 'IF') {
    if (cnt !== 3) return err('#ERR!')
    const c = scalar(n.args[0])
    if (isErr(c)) return c
    let truth
    if (c.k === 'b') truth = c.v
    else if (c.k === 'n') truth = c.v !== 0
    else return err('#VALUE!')
    return scalar(n.args[truth ? 1 : 2])
  }
  if (name === 'ABS') {
    if (cnt !== 1) return err('#ERR!')
    const x = toNum(scalar(n.args[0]))
    if (isErr(x)) return x
    return num(Math.abs(x.v))
  }
  if (!['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'].includes(name)) return err('#NAME?')
  if (cnt < 1) return err('#ERR!')
  const vals = []
  for (const a of n.args) for (const v of argValues(a)) vals.push(v)
  for (const v of vals) if (isErr(v)) return v
  if (name === 'COUNT') return num(vals.filter((v) => v.k === 'n').length)
  const nums = []
  for (const v of vals) {
    const x = toNum(v)
    if (isErr(x)) return x
    nums.push(x.v)
  }
  switch (name) {
    case 'SUM': return finite(nums.reduce((a, b) => a + b, 0))
    case 'MIN': return num(nums.reduce((a, b) => Math.min(a, b)))
    case 'MAX': return num(nums.reduce((a, b) => Math.max(a, b)))
    case 'AVG': return finite(nums.reduce((a, b) => a + b, 0) / nums.length)
  }
  return err('#ERR!')
}

function show(v) {
  if (v.k === 'e' || v.k === 't') return v.v
  if (v.k === 'b') return v.v ? 'TRUE' : 'FALSE'
  return String(Number(v.v.toPrecision(10)))
}

// ---------- output ----------
const keys = [...cells.keys()].sort((a, b) => a - b)
const out = []
for (const k of keys) {
  if (mode === 'values') out.push(`${addrStr(k)}=${show(cellValue(k))}`)
  else {
    const set = new Set()
    const f = info.get(k).formula
    if (f) collect(f.ast, set)
    out.push(`${addrStr(k)}:` + [...set].sort((a, b) => a - b).map((d) => ' ' + addrStr(d)).join(''))
  }
}
process.stdout.write(out.length ? out.join('\n') + '\n' : '')
"}

