#!/usr/bin/env node
import { readFileSync } from 'node:fs'

const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'
function fail(msg, code = 2) {
  process.stderr.write(msg + '\n')
  process.exit(code)
}

const args = process.argv.slice(2)
const mode = args[0]
let workers = 0
if (mode === 'waves' || mode === 'explain') {
  if (args.length !== 1) fail(USAGE)
} else if (mode === 'pack') {
  if (args.length !== 2) fail(USAGE)
  if (!/^[1-9][0-9]*$/.test(args[1])) fail('error: workers must be a positive integer')
  workers = Number(args[1])
} else fail(USAGE)

const text = readFileSync(0, 'utf8')
const lines = text.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cost = new Map()
const deps = new Map()
const used = []
const NAME = /^[A-Za-z0-9_.-]+$/
lines.forEach((raw, i) => {
  const n = i + 1
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) return
  const w = line.split(/\s+/)
  if (w[0] === 'task') {
    if (w.length !== 3) fail(`error: line ${n}: expected task <name> <cost>`)
    if (!NAME.test(w[1])) fail(`error: line ${n}: invalid task name ${w[1]}`)
    if (!/^[0-9]+$/.test(w[2])) fail(`error: line ${n}: cost must be a non-negative integer`)
    if (cost.has(w[1])) fail(`error: line ${n}: task ${w[1]} is declared twice`)
    cost.set(w[1], BigInt(w[2]))
  } else if (w[0] === 'dep') {
    if (w.length < 3) fail(`error: line ${n}: expected dep <name> <dependency>...`)
    for (const x of w.slice(1)) used.push(x)
    used.push
    if (!deps.has(w[1])) deps.set(w[1], new Set())
    for (const d of w.slice(2)) deps.get(w[1]).add(d)
  } else fail(`error: line ${n}: unknown directive ${w[0]}`)
})
for (const x of used) if (!cost.has(x)) fail(`error: unknown task ${x}`)

const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)
const names = [...cost.keys()].sort(cmp)
const dl = new Map(names.map((x) => [x, [...(deps.get(x) || [])].sort(cmp)]))

// cycle detection
const state = new Map()
const stack = []
function dfs(u) {
  state.set(u, 1)
  stack.push(u)
  for (const v of dl.get(u)) {
    const s = state.get(v)
    if (s === 1) {
      const c = stack.slice(stack.indexOf(v)).concat(v)
      fail('error: cycle: ' + c.join(' -> '), 3)
    }
    if (!s) dfs(v)
  }
  stack.pop()
  state.set(u, 2)
}
for (const x of names) if (!state.get(x)) dfs(x)

// start/finish/depth (memoised DFS; graph is acyclic)
const start = new Map(), finish = new Map(), depth = new Map()
function calc(u) {
  if (finish.has(u)) return
  let s = 0n, d = 0
  for (const v of dl.get(u)) {
    calc(v)
    if (finish.get(v) > s) s = finish.get(v)
    if (depth.get(v) + 1 > d) d = depth.get(v) + 1
  }
  start.set(u, s); finish.set(u, s + cost.get(u)); depth.set(u, d)
}
names.forEach(calc)
let total = 0n
for (const x of names) if (finish.get(x) > total) total = finish.get(x)

const out = []
if (mode === 'waves') {
  const ws = []
  for (const x of names) (ws[depth.get(x)] ||= []).push(x)
  ws.forEach((w, k) => out.push(`wave ${k}: ${w.join(' ')}`))
  out.push(`total ${total}`)
} else if (mode === 'explain') {
  for (const x of names) out.push(`${x} start=${start.get(x)} finish=${finish.get(x)} depth=${depth.get(x)}`)
  out.push(`total ${total}`)
} else {
  const rev = new Map(names.map((x) => [x, []]))
  for (const x of names) for (const d of dl.get(x)) rev.get(d).push(x)
  const prio = new Map()
  const pr = (u) => {
    if (prio.has(u)) return prio.get(u)
    let m = 0n
    for (const v of rev.get(u)) { const p = pr(v); if (p > m) m = p }
    prio.set(u, m + cost.get(u))
    return m + cost.get(u)
  }
  names.forEach(pr)
  const order = [...names].sort((a, b) => (prio.get(a) > prio.get(b) ? -1 : prio.get(a) < prio.get(b) ? 1 : cmp(a, b)))
  const fin = new Map()
  const freeAt = Array(workers).fill(0n)
  const runs = Array.from({ length: workers }, () => [])
  const pending = new Set(order)
  let t = 0n, makespan = 0n
  while (pending.size) {
    for (;;) {
      const wi = freeAt.findIndex((f) => f <= t)
      if (wi < 0) break
      const task = order.find((x) => pending.has(x) && dl.get(x).every((d) => fin.has(d) && fin.get(d) <= t))
      if (task === undefined) break
      pending.delete(task)
      const f = t + cost.get(task)
      fin.set(task, f)
      freeAt[wi] = f
      runs[wi].push(`${task}@${t}-${f}`)
      if (f > makespan) makespan = f
    }
    if (!pending.size) break
    t = freeAt.filter((f) => f > t).reduce((a, b) => (a < b ? a : b))
  }
  runs.forEach((r, i) => out.push(`worker ${i}:` + r.map((s) => ' ' + s).join('')))
  out.push(`makespan ${makespan}`)
}
process.stdout.write(out.join('\n') + '\n')
EOF
