import { readFileSync } from 'node:fs'

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'rounds' && mode !== 'tally') fail('error: usage: cli.js rounds|tally')

const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()

let names = null
const known = new Set()
const ballots = []
for (let i = 0; i < lines.length; i++) {
  const n = i + 1
  const line = lines[i].trim()
  if (line === '' || line.startsWith('#')) continue
  const t = line.split(/\s+/)
  if (t[0] === 'candidates') {
    if (names !== null) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (t.length < 2) fail(`error: line ${n}: expected candidates <name>...`)
    names = []
    for (const name of t.slice(1)) {
      if (!/^[A-Za-z0-9_-]+$/.test(name)) fail(`error: line ${n}: invalid candidate name ${name}`)
      if (known.has(name)) fail(`error: line ${n}: candidate ${name} is declared twice`)
      known.add(name)
      names.push(name)
    }
  } else if (t[0] === 'ballot') {
    if (names === null) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (t.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
    if (!/^[1-9][0-9]*$/.test(t[1])) fail(`error: line ${n}: count must be a positive integer`)
    const seen = new Set()
    for (const name of t.slice(2)) {
      if (!known.has(name)) fail(`error: line ${n}: unknown candidate ${name}`)
      if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is repeated`)
      seen.add(name)
    }
    ballots.push({ count: BigInt(t[1]), prefs: t.slice(2) })
  } else {
    fail(`error: line ${n}: unknown directive ${t[0]}`)
  }
}
if (names === null) fail('error: no candidates')

const total = ballots.reduce((s, b) => s + b.count, 0n)
const continuing = new Set(names)
const history = [] // Map per round
const out = []
let winner = null
let roundNo = 0
for (;;) {
  roundNo++
  const counts = new Map([...continuing].map((c) => [c, 0n]))
  let active = 0n
  for (const b of ballots) {
    const c = b.prefs.find((p) => continuing.has(p))
    if (c !== undefined) {
      counts.set(c, counts.get(c) + b.count)
      active += b.count
    }
  }
  history.push(counts)
  const listed = [...counts.entries()].sort((a, b) =>
    a[1] > b[1] ? -1 : a[1] < b[1] ? 1 : a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0)
  let line = `round ${roundNo}: ` + listed.map(([c, v]) => `${c}=${v}`).join(' ')
  line += ` exhausted=${total - active}`
  out.push(line)
  if (active === 0n) break
  const top = listed.find(([, v]) => v * 2n > active)
  if (top) { winner = top[0]; break }
  let min = null
  for (const v of counts.values()) if (min === null || v < min) min = v
  let tied = [...counts].filter(([, v]) => v === min).map(([c]) => c)
  let changed = true
  while (changed && tied.length > 1) {
    changed = false
    for (const h of history) {
      let m = null
      let allEq = true
      for (const c of tied) {
        const v = h.get(c)
        if (m !== null && v !== m) allEq = false
        if (m === null || v < m) m = v
      }
      if (!allEq) {
        tied = tied.filter((c) => h.get(c) === m)
        changed = true
        break
      }
    }
  }
  tied.sort()
  const elim = tied[tied.length - 1]
  continuing.delete(elim)
  out.push(`eliminated ${elim}`)
}
const end = winner === null ? 'no winner' : `winner ${winner}`
if (mode === 'rounds') process.stdout.write(out.join('\n') + '\n' + end + '\n')
else process.stdout.write(`rounds ${roundNo}\n${end}\n`)
EOF
node --test test/*.test.js 2>&1 | tail -12","description":"Write CLI and run tests"}

